using System;using Ashfall.Core;using Ashfall.Integration.Playable.Networking;using Ashfall.Integration.Playable.Match;
// Host custody/receipt regression, using the maintained Pair/KeepRaw pattern.
// Unity's R26LanSession.Drops native completion still needs the two-headset check.
partial class LobbyCases {
 internal static void R26DropRun(){int before=checks;foreach(string kind in new[]{"frag","zone","flash","smoke"})R26GrenadeDropReceipt(kind);foreach(string kind in new[]{"banana","soda","shaker"})R26FoodDropReceipt(kind);Console.WriteLine("PASS "+(checks-before)+" DROPS custody observations");}
 static void R26DropSetup(Pair pair,string hash){for(int i=0;i<5;i++)pair.Tick();StartRound(pair,new HazardWorld(),R24PlayableMatchRules.ForPreset("free_for_all","range").With("zone_enabled",false).With("protection",0f),hash);for(int i=0;i<4;i++)KeepRaw(pair,hash,0,8);Need(pair.Client.RequestLoot("cx4",1,true,new Float3(0,1.2f,.2f)),"Free one real guest slot");for(int i=0;i<4;i++)KeepRaw(pair,hash,0,8);}
 static void R26DropAt(Float3 actual,Float3 wanted,string label){Need(Math.Abs(actual.X-wanted.X)<.001f&&Math.Abs(actual.Y-wanted.Y)<.001f&&Math.Abs(actual.Z-wanted.Z)<.001f,label+" uses the accepted host position");}
 static void R26GrenadeDropReceipt(string kind){using(var pair=new Pair()){string hash=new string('b',64),id="r26/drop/"+kind;R26DropSetup(pair,hash);R24LanGrenadeState row;
  Need(pair.Host.RegisterSharedGrenade(id,kind,new Float3(0,1.2f,.2f)),kind+" world item registered");for(int i=0;i<3;i++)KeepRaw(pair,hash,0,8);
  Need(pair.Client.RequestGrenade(id,1,0,new Float3()),kind+" guest claim queued");for(int i=0;i<6;i++)KeepRaw(pair,hash,0,8);Need(pair.Client.TryReadGrenade(id,out row)&&row.Owner==pair.Client.OwnActor&&!row.Spent,kind+" guest owns the actual payload");
  Need(pair.Client.RequestGrenade(id,1,2,new Float3(20,1,0)),kind+" refused drop is queued, not locally accepted");for(int i=0;i<4;i++)KeepRaw(pair,hash,0,8);Need(pair.Client.TryReadGrenade(id,out row)&&row.Owner==pair.Client.OwnActor,kind+" out-of-reach request never releases custody");
  var at=new Float3(.3f,.4f,.4f);long command=pair.Client.CommandSequence;Need(pair.Client.RequestGrenade(id,1,2,at),kind+" ONE drop action queued");Need(pair.Client.TryReadGrenade(id,out row)&&row.Owner==pair.Client.OwnActor,kind+" BEFORE: immediate receipt read is still owned (the old callback returned false)");
  for(int i=0;i<6;i++)KeepRaw(pair,hash,0,8);Need(pair.Client.CommandSequence==command+1,kind+" no repeated press/second drop command needed");Need(pair.Host.TryReadGrenade(id,out row)&&row.Owner==""&&!row.Spent,kind+" host releases the same unspent payload");R26DropAt(row.Position,at,kind);
  Need(pair.Client.TryReadGrenade(id,out row)&&row.Owner==""&&!row.Spent,kind+" delayed free receipt is available to pending completion");R26DropAt(row.Position,at,kind+" guest");long revision=row.Revision;
  Need(pair.Client.RequestGrenade(id,1,2,at),kind+" duplicate command can be queued");for(int i=0;i<4;i++)KeepRaw(pair,hash,0,8);Need(pair.Host.TryReadGrenade(id,out row)&&row.Owner==""&&row.Revision==revision,kind+" duplicate drop does not republish/mint a payload");
  Need(pair.Client.RequestGrenade(id,1,0,new Float3()),kind+" same dropped payload can be reclaimed");for(int i=0;i<6;i++)KeepRaw(pair,hash,0,8);Need(pair.Client.TryReadGrenade(id,out row)&&row.Owner==pair.Client.OwnActor,kind+" reclaim receipt reaches guest");
  string hostId=id+"/host";Need(pair.Host.RequestLoot("cx4",1,true,new Float3(8,1.2f,0))&&pair.Host.RegisterSharedGrenade(hostId,kind,new Float3(8,1.2f,.2f))&&pair.Host.RequestGrenade(hostId,1,0,new Float3()),kind+" host control owns a payload");var hostAt=new Float3(8.3f,.4f,.4f);Need(pair.Host.RequestGrenade(hostId,1,2,hostAt)&&pair.Host.TryReadGrenade(hostId,out row)&&row.Owner=="",kind+" host drop remains synchronous");R26DropAt(row.Position,hostAt,kind+" host");
 }}
 static void R26FoodDropReceipt(string kind){using(var pair=new Pair()){string hash=new string('b',64),id="r26/drop/"+kind;R26DropSetup(pair,hash);R24LanFoodState row;
  Need(pair.Host.RegisterSharedFood(id,kind,new Float3(0,1.2f,.2f)),kind+" world item registered");for(int i=0;i<3;i++)KeepRaw(pair,hash,0,8);
  Need(pair.Client.RequestFood(id,1,0,new Float3()),kind+" guest claim queued");for(int i=0;i<6;i++)KeepRaw(pair,hash,0,8);Need(pair.Client.TryReadFood(id,out row)&&row.Owner==pair.Client.OwnActor&&!row.Consumed,kind+" guest owns the actual food");
  Need(pair.Client.RequestFood(id,1,2,new Float3(20,1,0)),kind+" refused drop is queued, not locally accepted");for(int i=0;i<4;i++)KeepRaw(pair,hash,0,8);Need(pair.Client.TryReadFood(id,out row)&&row.Owner==pair.Client.OwnActor,kind+" out-of-reach request never releases custody");
  var at=new Float3(.3f,.4f,.4f);long command=pair.Client.CommandSequence;Need(pair.Client.RequestFood(id,1,2,at),kind+" ONE drop action queued");Need(pair.Client.TryReadFood(id,out row)&&row.Owner==pair.Client.OwnActor,kind+" BEFORE: immediate receipt read is still owned (the old callback returned false)");
  for(int i=0;i<6;i++)KeepRaw(pair,hash,0,8);Need(pair.Client.CommandSequence==command+1,kind+" no repeated press/second drop command needed");Need(pair.Host.TryReadFood(id,out row)&&row.Owner==""&&!row.Consumed,kind+" host releases the same unconsumed food");R26DropAt(row.Position,at,kind);
  Need(pair.Client.TryReadFood(id,out row)&&row.Owner==""&&!row.Consumed,kind+" delayed free receipt is available to pending completion");R26DropAt(row.Position,at,kind+" guest");long revision=row.Revision;
  Need(pair.Client.RequestFood(id,1,2,at),kind+" duplicate command can be queued");for(int i=0;i<4;i++)KeepRaw(pair,hash,0,8);Need(pair.Host.TryReadFood(id,out row)&&row.Owner==""&&row.Revision==revision,kind+" duplicate drop does not republish/mint food");
  Need(pair.Client.RequestFood(id,1,0,new Float3()),kind+" same dropped food can be reclaimed");for(int i=0;i<6;i++)KeepRaw(pair,hash,0,8);Need(pair.Client.TryReadFood(id,out row)&&row.Owner==pair.Client.OwnActor,kind+" reclaim receipt reaches guest");
  string hostId=id+"/host";Need(pair.Host.RequestLoot("cx4",1,true,new Float3(8,1.2f,0))&&pair.Host.RegisterSharedFood(hostId,kind,new Float3(8,1.2f,.2f))&&pair.Host.RequestFood(hostId,1,0,new Float3()),kind+" host control owns food");var hostAt=new Float3(8.3f,.4f,.4f);Need(pair.Host.RequestFood(hostId,1,2,hostAt)&&pair.Host.TryReadFood(hostId,out row)&&row.Owner=="",kind+" host drop remains synchronous");R26DropAt(row.Position,hostAt,kind+" host");
 }}
}
